fn g6(x: f32) -> String {
    if x.is_nan() { return if x.is_sign_negative() {"-nan".into()} else {"nan".into()}; }
    if x.is_infinite() { return if x < 0.0 {"-inf".into()} else {"inf".into()}; }
    if x == 0.0 { return if x.is_sign_negative() {"-0".into()} else {"0".into()}; }
    let e = format!("{:.5e}", x);
    let (mant, exps) = e.split_once('e').unwrap();
    let exp: i32 = exps.parse().unwrap();
    if exp < -4 || exp >= 6 {
        let mut m = mant.to_string();
        if m.contains('.') { while m.ends_with('0') { m.pop(); } if m.ends_with('.') { m.pop(); } }
        let sign = if exp < 0 {'-'} else {'+'};
        format!("{}e{}{:02}", m, sign, exp.abs())
    } else {
        let prec = (5 - exp) as usize;
        let mut s = format!("{:.*}", prec, x);
        if s.contains('.') { while s.ends_with('0') { s.pop(); } if s.ends_with('.') { s.pop(); } }
        s
    }
}
fn luma_f32(r:f32,g:f32,b:f32)->f32 { 0.2126f32*r + 0.7152f32*g + 0.0722f32*b }
fn luma_f64(r:f32,g:f32,b:f32)->f32 { (0.2126f64*(r as f64) + 0.7152f64*(g as f64) + 0.0722f64*(b as f64)) as f32 }
fn luma_fma(r:f32,g:f32,b:f32)->f32 { (0.0722f32).mul_add(b, (0.7152f32).mul_add(g, 0.2126f32*r)) }
fn luma_601(r:f32,g:f32,b:f32)->f32 { 0.299f32*r + 0.587f32*g + 0.114f32*b }

fn line(r:f32,g:f32,b:f32, f: fn(f32,f32,f32)->f32) -> String {
    let l = f(r,g,b);
