            let digits: String = mant.chars().filter(|c|c.is_ascii_digit()).collect();
            // 6 sig digits kept -> digits[6..] must be "5" followed by zeros
            if digits.len()>7 && digits.as_bytes()[6]==b'5' && digits[7..].bytes().all(|b|b==b'0') {
                found.push(format!("{}", f));
